bicepWiring.disableLocalAuth:
properties: {
  sku: { name: skuName, tier: skuName }
  disableLocalAuth: true
  minimumTlsVersion: '1.2'
}

bicepWiring.createQueue:
resource queue 'Microsoft.ServiceBus/namespaces/queues@2022-10-01-preview' = {
  parent: serviceBusNamespace
  name: queueName
  properties: {
    maxDeliveryCount: 10
    lockDuration: 'PT1M'
    defaultMessageTimeToLive: 'P14D'
  }
}

sdkInitPattern.typescript:
import { ServiceBusClient } from '@azure/service-bus';
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential();
const client = new ServiceBusClient(process.env.AZURE_SERVICE_BUS_NAMESPACE!, credential);

// Send
const sender = client.createSender(process.env.AZURE_SERVICE_BUS_QUEUE_NAME!);
await sender.sendMessages({ body: payload });

// Receive
const receiver = client.createReceiver(process.env.AZURE_SERVICE_BUS_QUEUE_NAME!);
const messages = await receiver.receiveMessages(10);
for (const msg of messages) { await receiver.completeMessage(msg); }
